// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Inter');

const { fontFamily } = loadFont();



export type AppleCalendarProps = Record<string, any>;

const AppleCalendar: React.FC<AppleCalendarProps> = ({
  backgroundColor = "#F2F2F7",
  transparentBackground = false,
  durationInSeconds = 6,
  month = "October",
  year = "2024",
  startDay = 12,
  endDay = 24,
  strikeColor = "#34C759", // Changed default to green
  cardColor = "#FFFFFF",
  textColor = "#1C1C1E",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Responsive sizing
  const cardSize = Math.min(width, height) * 0.85;
  const padding = cardSize * 0.08;
  const fontSizeHeader = cardSize * 0.06;
  const fontSizeDay = cardSize * 0.035;
  const fontSizeWeekday = cardSize * 0.025;
  
  // Calendar Grid Constants
  const DAYS_OF_WEEK = ["S", "M", "T", "W", "T", "F", "S"];
  const START_WEEKDAY_OFFSET = 2; // Arbitrary starts on Tuesday
  const TOTAL_DAYS = 31;
  
  const daysArray = Array.from({ length: TOTAL_DAYS }, (_, i) => i + 1);
  const offsetArray = Array.from({ length: START_WEEKDAY_OFFSET }, (_, i) => i);
  
  // Animation Timing
  const INTRO_DURATION = 30;
  const STRIKE_DELAY_FRAMES = 5;
  
  const safeStart = Math.min(startDay, endDay);
  const safeEnd = Math.max(startDay, endDay);

  // Filter target days to only include Monday (1), Wednesday (3), and Friday (5)
  const targetDays = daysArray.filter(day => {
    const isWithinRange = day >= safeStart && day <= safeEnd;
    const weekdayIndex = (START_WEEKDAY_OFFSET + (day - 1)) % 7;
    const isTargetWeekday = weekdayIndex === 1 || weekdayIndex === 3 || weekdayIndex === 5;
    return isWithinRange && isTargetWeekday;
  });

  const lastTargetDay = targetDays.length > 0 ? targetDays[targetDays.length - 1] : -1;

  // Card Entrance Animation
  const cardEntrance = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 100 },
  });
  
  const cardY = interpolate(cardEntrance, [0, 1], [100, 0]);
  const cardOpacity = interpolate(cardEntrance, [0, 1], [0, 1]);

  return (
    <AbsoluteFill style={{ 
      backgroundColor: bgColor, 
      fontFamily,
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      transition: "none",
    }}>
      <div style={{
        width: cardSize,
        height: cardSize,
        backgroundColor: cardColor,
        borderRadius: cardSize * 0.06,
        boxShadow: "0 20px 40px rgba(0,0,0,0.08), 0 4px 12px rgba(0,0,0,0.04)",
        padding: padding,
        display: "flex",
        flexDirection: "column",
        opacity: cardOpacity,
        transform: `translateY(${cardY}px)`,
        transition: "none",
      }}>
        
        {/* Header */}
        <div style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          marginBottom: cardSize * 0.06,
          transition: "none",
        }}>
          <div style={{ 
            fontSize: fontSizeHeader, 
            fontWeight: 700, 
            letterSpacing: "-0.02em",
            transition: "none",
          }}>
            <span style={{ color: strikeColor, transition: "none" }}>{month}</span>
            <span style={{ color: textColor, opacity: 0.8, marginLeft: cardSize * 0.015, transition: "none" }}>{year}</span>
          </div>
          <div style={{ 
            display: "flex", 
            gap: cardSize * 0.04, 
            color: strikeColor, 
            fontWeight: 600, 
            fontSize: fontSizeHeader * 0.7,
            opacity: 0.8,
            transition: "none",
          }}>
             <span>&lt;</span>
             <span>&gt;</span>
          </div>
        </div>

        {/* Days of Week Row */}
        <div style={{
          display: "grid",
          gridTemplateColumns: "repeat(7, 1fr)",
          marginBottom: cardSize * 0.02,
          transition: "none",
        }}>
          {DAYS_OF_WEEK.map((d, i) => (
            <div key={`dow-${i}`} style={{
              textAlign: "center",
              fontSize: fontSizeWeekday,
              fontWeight: 600,
              color: textColor,
              opacity: 0.3,
              transition: "none",
            }}>
              {d}
            </div>
          ))}
        </div>

        {/* Calendar Grid */}
        <div style={{
          display: "grid",
          gridTemplateColumns: "repeat(7, 1fr)",
          rowGap: cardSize * 0.03,
          columnGap: cardSize * 0.01,
          flex: 1,
          transition: "none",
        }}>
          {/* Empty Offsets */}
          {offsetArray.map(i => (
            <div key={`offset-${i}`} style={{ transition: "none" }} />
          ))}

          {/* Actual Days */}
          {daysArray.map(day => {
            const strikeIndex = targetDays.indexOf(day);
            const isTarget = strikeIndex !== -1;
            const strikeStartFrame = isTarget ? INTRO_DURATION + strikeIndex * STRIKE_DELAY_FRAMES : 0;
            
            // Strike Animation
            const lineProgress = isTarget ? spring({
              frame: frame - strikeStartFrame,
              fps,
              config: { damping: 14, stiffness: 120 },
            }) : 0;

            // Pulse Animation for Final Struck Day
            let scale = 1;
            if (isTarget && day === lastTargetDay && frame > strikeStartFrame) {
              const pulseProg = spring({
                frame: frame - (strikeStartFrame + 6),
                fps,
                config: { damping: 10, mass: 0.8 },
              });
              scale = 1 + Math.sin(pulseProg * Math.PI) * 0.25;
            }

            return (
              <div key={`day-${day}`} style={{
                position: "relative",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                aspectRatio: "1/1",
                transition: "none",
              }}>
                <div style={{
                  fontSize: fontSizeDay,
                  fontWeight: 500,
                  color: textColor,
                  transform: `scale(${scale})`,
                  transformOrigin: "center",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  width: "100%",
                  height: "100%",
                  transition: "none",
                }}>
                  {day}
                  
                  {isTarget && (
                    <div style={{
                      position: "absolute",
                      inset: 0,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "center",
                      transition: "none",
                      pointerEvents: "none",
                    }}>
                      <svg
                        viewBox="0 0 24 24"
                        style={{
                          width: "75%",
                          height: "75%",
                          overflow: "visible",
                          filter: "drop-shadow(0px 2px 3px rgba(0,0,0,0.15))",
                          transition: "none",
                        }}
                      >
                        <path
                          d="M 4 12 L 10 18 L 20 6"
                          fill="none"
                          stroke={strikeColor}
                          strokeWidth={3.5}
                          strokeLinecap="round"
                          strokeLinejoin="round"
                          pathLength={1}
                          strokeDasharray="2 2"
                          strokeDashoffset={interpolate(lineProgress, [0, 1], [2, 1])}
                          style={{
                            opacity: interpolate(lineProgress, [0, 0.1], [0, 1], { extrapolateRight: "clamp" }),
                            transition: "none",
                          }}
                        />
                      </svg>
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default AppleCalendar;